export function Sso({
  heading = "{{heading}}",
  orgName = "{{orgName}}",
  primaryProvider = "{{primaryProvider}}",
  showEmailFallback = {{showEmailFallback}},
  accent = "{{accent}}",
}) {
  const btn = { display: "block", width: "100%", padding: 10, borderRadius: 8, border: "1.5px solid #24143030", background: "#FAF7F2", fontWeight: 600, cursor: "pointer", marginBottom: 10, font: "inherit" };
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: 22, borderRadius: 14, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 17 }}>{heading}</h3>
      <p style={{ margin: "0 0 18px", fontSize: 12, color: "#24143099" }}>Managed by {orgName}</p>
      <button type="button" style={{ ...btn, background: accent, color: "#FAF7F2", borderColor: accent }}>Continue with {primaryProvider}</button>
      <button type="button" style={btn}>Continue with SAML</button>
      {showEmailFallback && (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "14px 0", fontSize: 12, color: "#24143077" }}>
            <span style={{ flex: 1, height: 1, background: "#24143020" }} /><span>or</span><span style={{ flex: 1, height: 1, background: "#24143020" }} />
          </div>
          <label style={{ display: "block" }}>
            <span style={{ display: "block", marginBottom: 5, fontWeight: 600, fontSize: 13 }}>Work email</span>
            <input type="email" autoComplete="username" placeholder="you@company.com" style={{ width: "100%", boxSizing: "border-box", padding: "9px 10px", borderRadius: 8, border: "1.5px solid #24143030", font: "inherit" }} />
          </label>
        </>
      )}
    </div>
  );
}
